import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { verifyDeletedFileColors } from './output-differences.mjs';

const dir=process.env.DELTA_BENCH_DIR||'/tmp/delta-merge-2026-11-11';
const manifest=JSON.parse(fs.readFileSync(path.join(dir,'manifest.json')));
const env={...process.env,...manifest.controls.environment};
delete env.DELTA_FEATURES;
const expected={};
for(const suite of ['isolated','configured','native','hunk']){
  const data=JSON.parse(fs.readFileSync(path.join(dir,`clean-${suite}.json`)));
  for(const item of data.results){
    if(item.identical)continue;
    const prefix=path.join(dir,'outputs',suite,`${item.fixture}-${item.mode}`);
    const before=fs.readFileSync(prefix+'-before.bin'),after=fs.readFileSync(prefix+'-clean.bin');
    const input=fs.readFileSync(manifest.fixtures.find(f=>f.name===item.fixture).path);
    let proof;
    if(suite==='hunk'&&item.fixture==='mixed-layout'){
      assert.equal(JSON.parse(fs.readFileSync(path.join(dir,'contracts.json'))).passed,24);
      proof={reason:'New per-hunk layout; verified mixed-layout metadata and separate gutters in caller contracts and Rust expected-output tests'};
    }else if(suite!=='isolated'&&item.args.includes('--side-by-side')||suite==='hunk'&&!['large-context','deleted-rust'].includes(item.fixture)){
      const args=item.args.filter(x=>x!=='--side-by-side'&&x!=='--side-by-side=hunk').map(x=>x===manifest.configuration.path?path.join(dir,'configured-side.gitconfig'):x);
      const reference=spawnSync(path.join(dir,'before'),args,{input,env,maxBuffer:96*1024*1024,timeout:60000});
      assert.equal(reference.status,0,String(reference.stderr));
      proof=verifyDeletedFileColors(input,reference.stdout,after);
      proof.precedence='Candidate CLI activation matches baseline Git-config activation, apart from the separately checked deleted-file fix';
    }else proof=verifyDeletedFileColors(input,before,after);
    expected[`${suite}/${item.fixture}/${item.mode}`]={before_sha256:item.before_sha256,after_sha256:item.after_sha256,...proof};
  }
}
fs.writeFileSync(path.join(dir,'expected-differences.json'),JSON.stringify(expected,null,2)+'\n');
console.log(`${Object.keys(expected).length} intentional output differences verified`);

