import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { performance } from 'node:perf_hooks';
import { verifyDeletedFileColors } from './output-differences.mjs';

const root = process.env.DELTA_BENCH_DIR || '/tmp/delta-merge-2026-11-11';
const manifest = JSON.parse(fs.readFileSync(path.join(root, 'manifest.json')));
const [operation = 'baseline', suite = 'isolated', label = operation, count = '15'] = process.argv.slice(2);
const runs = Number(count);
const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const common = ['--paging=never', '--width=100', '--true-color=always', ...(suite === 'isolated' ? [] : ['--config', manifest.configuration.path])];
const explicitGutters=process.env.DELTA_BENCH_EXPLICIT_GUTTERS==='1';
if(explicitGutters)common.push('--line-numbers-left-style','#6c7086','--line-numbers-right-style','#6c7086','--line-numbers-minus-style','bold #f38ba8','--line-numbers-plus-style','bold #a6e3a1','--line-numbers-zero-style','#6c7086');
const links = ['--hyperlinks', '--hyperlinks-file-link-format=lazygit-edit://{path}:{line}'];
const modes = [['unified', []], ['side-by-side', ['--side-by-side']], ['no-syntax', ['--syntax-theme=none']]];
const ordinary = ['empty', 'tiny', 'unicode', 'long-lines', 'unpaired', 'rust-history', 'go-small', 'go-history'];
const cases = [];
if (suite === 'diagnostic') {
  cases.push({fixture:'large-context',mode:'side-by-side',args:[...common,...links,'--side-by-side']});
} else if (suite === 'native') {
  for (const fixture of ['empty', 'unicode', 'go-30', 'go-1000', 'go-12000', 'go-history-colored']) {
    for (const [mode, args] of modes.slice(0, 2)) cases.push({fixture, mode, args: [...common, ...links, '--lazygit-compat', ...args]});
  }
} else if (suite === 'hunk') {
  for (const fixture of ['tiny', 'unicode', 'mixed-layout', 'large-context', 'go-12000', 'deleted-rust']) {
    cases.push({fixture, mode: 'hunk', args: [...common, ...links, '--side-by-side=hunk'], beforeArgs: [...common, ...links, ...(['large-context', 'deleted-rust'].includes(fixture) ? [] : ['--side-by-side'])]});
  }
} else {
  for (const fixture of ordinary) for (const [mode, args] of modes) {
    cases.push({fixture, mode, args: [...common, ...(suite === 'isolated' ? ['--no-gitconfig', '--dark'] : links), ...args]});
  }
}
const equivalent = process.env.DELTA_BENCH_EQUIVALENT_SIDE === '1';
if (equivalent) for (const item of cases) {
  if (item.args.includes('--side-by-side')) item.beforeArgs=item.args.filter(x=>x!=='--side-by-side').map(x=>x===manifest.configuration.path?path.join(root,'configured-side.gitconfig'):x);
}
const env = {...process.env, ...manifest.controls.environment,
  GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: suite === 'isolated' ? '/dev/null' : manifest.configuration.path, GIT_CONFIG_COUNT: '0'};
if (suite === 'isolated') delete env.BAT_THEME;
else delete env.DELTA_FEATURES;
const binaries = ['before', operation === 'baseline' ? 'before' : (process.env.DELTA_BENCH_AFTER || 'after')].map(p => path.resolve(root, p));
const outputsDir = path.join(root, 'outputs', suite+(equivalent?'-equivalent':'')+(explicitGutters?'-explicit':''));
fs.mkdirSync(outputsDir, {recursive: true});
if (suite !== 'isolated') {
  for (const binary of new Set(binaries)) {
    const config = spawnSync(binary, ['--config', manifest.configuration.path, '--show-config'], {env, encoding:'utf8'});
    if (config.status !== 0 || !config.stdout.includes('Catppuccin Mocha') || !config.stdout.includes('catppuccin-mocha')) throw new Error(`Configured feature/theme not active: ${binary}`);
  }
}
function render(index, item, input, capture = false) {
  const start = performance.now();
  const result = spawnSync(binaries[index], index === 0 ? (item.beforeArgs || item.args) : item.args,
    {input, env, stdio: ['pipe', capture ? 'pipe' : 'ignore', 'pipe'], maxBuffer: 96 * 1024 * 1024, timeout: 60000});
  const ms = performance.now() - start;
  if (result.error || result.status !== 0) throw new Error(`${item.fixture}/${item.mode}: ${result.error || String(result.stderr)}`);
  return {output: result.stdout, ms};
}
function stats(samples) {
  const sorted = [...samples].sort((a,b) => a-b);
  const median = sorted[Math.floor(sorted.length/2)];
  const deviations = samples.map(x => Math.abs(x-median)).sort((a,b) => a-b);
  return {median_ms: median, mad_ms: deviations[Math.floor(deviations.length/2)], samples_ms: samples};
}
const selected = process.env.DELTA_BENCH_CASES ? new Set(process.env.DELTA_BENCH_CASES.split(',')) : null;
const results = [];
for (const item of cases) {
  const id = `${item.fixture}/${item.mode}`;
  if (selected && !selected.has(id)) continue;
  const fixture = manifest.fixtures.find(f => f.name === item.fixture);
  const input = fs.readFileSync(fixture.path);
  if (sha(input) !== fixture.sha256) throw new Error(`Fixture changed: ${fixture.name}`);
  const beforeOutput = render(0, item, input, true).output;
  const beforePath = path.join(outputsDir, `${item.fixture}-${item.mode}-before.bin`);
  if (operation === 'baseline' || (equivalent||explicitGutters) && !fs.existsSync(beforePath)) fs.writeFileSync(beforePath, beforeOutput);
  else if (!beforeOutput.equals(fs.readFileSync(beforePath))) throw new Error(`Baseline output changed: ${id}`);
  const afterOutput = operation === 'baseline' ? beforeOutput : render(1, item, input, true).output;
  const afterPath = path.join(outputsDir, `${item.fixture}-${item.mode}-${label}.bin`);
  if (operation !== 'baseline') fs.writeFileSync(afterPath, afterOutput);
  const identical = beforeOutput.equals(afterOutput);
  if (operation === 'verify') {
    results.push({...item, identical, before_sha256: sha(beforeOutput), after_sha256: sha(afterOutput), before_bytes: beforeOutput.length, after_bytes: afterOutput.length});
    continue;
  }
  if (operation === 'compare' && !identical) {
    const approvalPath = path.join(root, 'expected-differences.json');
    const accepted = equivalent||explicitGutters ? (verifyDeletedFileColors(input,beforeOutput,afterOutput),{before_sha256:sha(beforeOutput),after_sha256:sha(afterOutput)}) : fs.existsSync(approvalPath) ? JSON.parse(fs.readFileSync(approvalPath))[`${suite}/${id}`] : null;
    if (!accepted || accepted.before_sha256 !== sha(beforeOutput) || accepted.after_sha256 !== sha(afterOutput)) throw new Error(`Unverified output difference: ${suite}/${id}`);
  }
  const times = [[], []];
  for (let warmup=0; warmup<3; warmup++) {
    render(0,item,input);
    if (operation !== 'baseline') render(1,item,input);
  }
  for (let run=0; run<runs; run++) {
    for (const index of operation === 'baseline' ? [0] : run%2 ? [1,0] : [0,1]) times[index].push(render(index,item,input).ms);
  }
  const before = stats(times[0]), after = operation === 'baseline' ? null : stats(times[1]);
  const result = {...item, input_sha256: fixture.sha256, input_bytes: input.length,
    identical, before_sha256: sha(beforeOutput), after_sha256: sha(afterOutput), before, after,
    change_percent: after ? 100*(after.median_ms/before.median_ms-1) : null};
  results.push(result);
  process.stderr.write(`${suite}/${id} ${before.median_ms.toFixed(2)}${after ? ` -> ${after.median_ms.toFixed(2)} (${result.change_percent.toFixed(2)}%)` : ''}\n`);
}
const output = {created_at: new Date().toISOString(), operation, suite, label, runs, warmups: 3, equivalentSideConfiguration:equivalent, explicitGutters, manifest_sha256: sha(fs.readFileSync(path.join(root,'manifest.json'))),
  binaries: binaries.map(p=>({path:p,sha256:sha(fs.readFileSync(p))})), env: Object.fromEntries(Object.keys(manifest.controls.environment).concat(['GIT_CONFIG_NOSYSTEM','GIT_CONFIG_GLOBAL','GIT_CONFIG_COUNT']).map(k=>[k,env[k]])),
  controls: manifest.controls, results};
fs.writeFileSync(path.join(root, `${label}-${suite}.json`), JSON.stringify(output,null,2)+'\n');
console.log(path.join(root, `${label}-${suite}.json`));

scriptSources.build-native-search.mjs:
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const dir='/tmp/delta-merge-2026-11-11';
const registry='/home/lalvarezt/.cargo/registry/src/index.crates.io-1949cf8c6b5b557f';
const onig=path.join(dir,'onig-default-search-probe');
const syntect=path.join(dir,'syntect-default-search-probe');
fs.cpSync(path.join(registry,'onig-6.5.3'),onig,{recursive:true});
fs.cpSync(path.join(registry,'syntect-5.3.0'),syntect,{recursive:true});
let source=fs.readFileSync(path.join(onig,'src/lib.rs'),'utf8');
const start=source.indexOf('    pub fn search_with_param<T>(');
const end=source.indexOf('\n    /// Returns true',start);
if(start<0||end<0)throw new Error('Could not locate fallible regex search');
let method=source.slice(start,end)
 .replace('search_with_param<T>','search_with_default<T>')
 .replace('        match_param: MatchParam,\n','')
 .replace('onig_sys::onig_search_with_param(','onig_sys::onig_search(')
 .replace('                match_param.as_raw(),\n','');
if(method.includes('match_param'))throw new Error('Unexpected explicit parameter use');
const docStart=source.lastIndexOf('    /// Search pattern',start);
if(docStart<0)throw new Error('Could not preserve the explicit-parameter method documentation');
source=source.slice(0,docStart)+'    /// Search using the native stack-allocated default parameters.\n'+method+'\n'+source.slice(docStart);
fs.writeFileSync(path.join(onig,'src/lib.rs'),source);
let regex=fs.readFileSync(path.join(syntect,'src/parsing/regex.rs'),'utf8');
regex=regex.replace('use onig::{MatchParam, RegexOptions','use onig::{RegexOptions')
 .replace('self.regex.search_with_param(','self.regex.search_with_default(')
 .replace('                MatchParam::default(),\n','');
fs.writeFileSync(path.join(syntect,'src/parsing/regex.rs'),regex);
const probe=path.join(dir,'parser-probe');
let manifest=fs.readFileSync(path.join(probe,'Cargo.toml.before'),'utf8');
manifest+='\n[patch.crates-io]\nonig = { path = "'+onig+'" }\nsyntect = { path = "'+syntect+'" }\n';
fs.writeFileSync(path.join(probe,'Cargo.toml'),manifest);
const result=spawnSync('just',['build'],{cwd:probe,env:{...process.env,CARGO_TARGET_DIR:'/home/lalvarezt/git-repos/delta/target'},encoding:'utf8',timeout:240000,maxBuffer:20*1024*1024});
fs.writeFileSync(path.join(dir,'native-search-build.log'),(result.stdout||'')+(result.stderr||''));
if(result.status!==0)throw new Error(result.stderr);
fs.copyFileSync('/home/lalvarezt/git-repos/delta/target/release/delta',path.join(dir,'parser-stack-default'));
console.log('Native default-search probe built.');

scriptSources.check-losses.mjs:
import fs from 'node:fs';
const file=process.argv[2];
const data=JSON.parse(fs.readFileSync(file));
const median=a=>[...a].sort((x,y)=>x-y)[Math.floor(a.length/2)];
let seed=123456789;
const random=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/2**32;};
export function pairedInterval(before,after){
  const differences=before.map((x,i)=>Math.log(after[i]/x));
  const boots=Array.from({length:5000},()=>median(differences.map(()=>differences[Math.floor(random()*differences.length)]))).sort((a,b)=>a-b);
  const percent=x=>100*(Math.exp(x)-1);
  return {paired_median_percent:percent(median(differences)),ci95_percent:[percent(boots[125]),percent(boots[4874])]};
}
const rows=data.results.map(x=>({case:x.fixture+'/'+x.mode,before_ms:x.before.median_ms,after_ms:x.after.median_ms,...pairedInterval(x.before.samples_ms,x.after.samples_ms)}));
fs.writeFileSync(file.replace(/\.json$/, '-intervals.json'),JSON.stringify(rows,null,2)+'\n');
const losses=rows.filter(x=>x.ci95_percent[0]>0);
console.log(JSON.stringify({cases:rows.length,detectedLosses:losses},null,2));
process.exitCode=losses.length?1:0;

