import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
const dir=process.env.DELTA_BENCH_DIR||'/tmp/delta-merge-2026-11-11';
const repo=process.cwd();
const proxy=path.join(dir,'verify-runner-delta');
const proxyText=`#!/usr/bin/env node
const cp=require('child_process');
const args=process.argv.slice(2);
const isolated=args.includes('--no-gitconfig');
const config=cp.spawnSync(${JSON.stringify(path.join(dir,'before'))},['--config',${JSON.stringify(path.join(dir,'configured.gitconfig'))},...(isolated?['--no-gitconfig']:[]),'--show-config'],{env:process.env,encoding:'utf8'});
const configured=config.stdout.includes('catppuccin-mocha')&&config.stdout.includes('Catppuccin Mocha');
if(config.status!==0||configured===isolated){process.stderr.write('Effective configured feature/theme mismatch');process.exit(91);}
const result=cp.spawnSync(${JSON.stringify(path.join(dir,'before'))},['--config',${JSON.stringify(path.join(dir,'configured.gitconfig'))},...args],{env:process.env,stdio:'inherit'});
process.exit(result.status??92);
`;
fs.writeFileSync(proxy,proxyText,{mode:0o755});
const old=spawnSync('git',['show','df58082:etc/performance/compare.mjs'],{encoding:'utf8'});
assert.equal(old.status,0);
const beforeRunner=path.join(repo,'etc/performance/.compare-before-validation.mjs');
fs.writeFileSync(beforeRunner,old.stdout);
const env={...process.env};delete env.DELTA_FEATURES;
const results=[];
try {
  for(const [name,script,configured,expected]of[
    ['old-configured',beforeRunner,true,1],
    ['fixed-configured',path.join(repo,'etc/performance/compare.mjs'),true,0],
    ['fixed-isolated',path.join(repo,'etc/performance/compare.mjs'),false,0]
  ]){
    const r=spawnSync('node',[script,'--before',proxy,'--after',proxy,'--fixture','tiny','--mode','unified','--runs','3','--output',path.join(dir,`runner-${name}.json`),...(configured?['--gitconfig']:[])],{env,encoding:'utf8',timeout:30000});
    fs.writeFileSync(path.join(dir,`runner-${name}.log`),r.stdout+r.stderr);
    assert.equal(r.status,expected,`${name}: ${r.stderr.slice(0,400)}`);
    if(expected!==0)assert.ok(r.stderr.includes('Effective configured feature/theme mismatch'));
    results.push({name,exit:r.status,configuredFeatureVerified:expected===0&&configured,isolatedFeatureDisabled:!configured});
  }
} finally { fs.unlinkSync(beforeRunner); }
fs.writeFileSync(path.join(dir,'runner-validation.json'),JSON.stringify({results},null,2)+'\n');
console.log('Original runner fails the real-feature probe; fixed configured and isolated modes pass.');

