import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import assert from 'node:assert/strict';
import { stripVTControlCharacters } from 'node:util';
import { verifyDeletedFileColors } from './output-differences.mjs';

const dir = process.env.DELTA_BENCH_DIR || '/tmp/delta-merge-2026-11-11';
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json')));
const env = {...process.env, ...manifest.controls.environment, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: manifest.configuration.path, GIT_CONFIG_COUNT: '0'};
delete env.DELTA_FEATURES;
const sideConfig=path.join(dir,'configured-side.gitconfig');
fs.copyFileSync(manifest.configuration.path,sideConfig);
assert.equal(spawnSync('git',['config','--file',sideConfig,'delta.side-by-side','true']).status,0);
const checks = [];
function render(binary, input, args = [], environment = env) {
  const r = spawnSync(path.join(dir, binary), ['--paging=never', '--config', environment.GIT_CONFIG_GLOBAL, ...(args.some(x=>x.startsWith('--width')) ? [] : ['--width=100']), '--true-color=always', ...args], {input, env: environment, maxBuffer:96*1024*1024});
  assert.equal(r.status, 0, String(r.stderr));
  return r.stdout;
}
function test(name, fn) {
  try { fn(); } catch (error) { console.error(`FAILED: ${name}\n${error.message?.slice(0,400)}\n${error.stack?.split('\n').filter(l=>l.includes('contracts.mjs')).slice(0,2).join('\n')}`); process.exit(1); }
  checks.push(name);
  process.stderr.write(`PASS ${name}\n`);
}
const mixed = fs.readFileSync(path.join(dir, 'fixtures/mixed-layout.diff'), 'utf8');
const deleted = fs.readFileSync(path.join(dir, 'fixtures/deleted-rust.diff'), 'utf8');
function records(output) {
  return [...output.toString().matchAll(/\x1b\]1717;1;([a-zA-Z]);([^;]*);([^;]*);([^\x1b\x07]*)(?:\x1b\\|\x07)/g)]
    .map(m=>({kind:m[1],line:m[2],old:m[3],file:m[4]}));
}
function expectedRecords(input) {
  let file='', old=0, line=0, hunk=false;
  const result=[];
  for (const text of input.split('\n')) {
    if (text.startsWith('diff --git ')) hunk=false;
    if (text.startsWith('+++ b/')) file=text.slice(6);
    const header=text.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (header) {old=Number(header[1]);line=Number(header[2]);hunk=true;continue;}
    if (!hunk) continue;
    if (text.startsWith('-')) result.push({kind:'d',line:String(line),old:String(old++),file});
    else if (text.startsWith('+')) result.push({kind:'a',line:String(line++),old:'',file});
    else if (text.startsWith(' ')) {result.push({kind:'c',line:String(line++),old:'',file});old++;}
  }
  return result;
}
const identity = r=>JSON.stringify(r);
for (const width of [40,41,100]) for (const lineNumbers of [true,false]) for (const native of [false,true]) {
  test(`mixed metadata width=${width} numbers=${lineNumbers} native=${native}`,()=>{
    const output=render('after',mixed,['--side-by-side=hunk',`--width=${width}`, '--hyperlinks','--hyperlinks-file-link-format=lazygit-edit://{path}:{line}',...(native?['--lazygit-compat']:[])],{...env,DELTA_FEATURES:lineNumbers?undefined:'+ -line-numbers'});
    const actual=records(output).filter(r=>['a','d','c'].includes(r.kind));
    assert.deepEqual([...new Set(actual.map(identity))].sort(),[...new Set(expectedRecords(mixed).map(identity))].sort());
    assert.ok(output.includes(Buffer.from('\x1b]1717;1\x1b\\')));
    assert.ok(output.includes(Buffer.from('lazygit-edit://')));
    assert.ok(!stripVTControlCharacters(output.toString()).includes('1717;'));
  });
}
for (const mode of [[],['--side-by-side'],['--side-by-side=hunk'],['--color-only']]) {
  test(`deleted syntax ${mode.join(' ') || 'unified'}`,()=>{
    const after=render('after',deleted,[...mode,'--minus-style=syntax','--minus-emph-style=syntax']);
    const plain=render('after',deleted,[...mode,'--minus-style=normal','--minus-emph-style=normal']);
    assert.notDeepEqual(after,plain);
    assert.equal(stripVTControlCharacters(after.toString()),stripVTControlCharacters(plain.toString()));
  });
}
test('hunk mode minimum width falls back byte-for-byte',()=>{
  assert.deepEqual(render('after',mixed,['--side-by-side=hunk,101']),render('after',mixed,['--side-by-side=false']));
});
test('color-only preserves the interactive patch input contract',()=>{
  for(const binary of ['before','after']) assert.equal(stripVTControlCharacters(render(binary,mixed,['--color-only','--side-by-side']).toString()),stripVTControlCharacters(render(binary,mixed,['--color-only']).toString()));
  assert.deepEqual(render('after',mixed,['--color-only','--side-by-side=hunk']),render('after',mixed,['--color-only','--side-by-side']));
});
const featuresFile=path.join(dir,'feature-formats.gitconfig');
fs.writeFileSync(featuresFile,'[delta]\n features=mine\n[delta "mine"]\n line-numbers-left-format="{nm:>1}L"\n line-numbers-right-format="{np:>1}R"\n');
test('CLI side-by-side keeps custom feature formats',()=>{
  const output=render('after',mixed,['--side-by-side'],{...env,GIT_CONFIG_GLOBAL:featuresFile});
  const text=stripVTControlCharacters(output.toString());
  assert.ok(text.includes('1L'));
  assert.ok(text.includes('1R'));
});
test('hunk mode keeps separate unified and panel formats',()=>{
  const formatFile=path.join(dir,'panel-formats.gitconfig');
  fs.writeFileSync(formatFile,'[delta "side-by-side"]\n line-numbers-left-format="{nm:>1}A"\n line-numbers-right-format="{np:>1}B"\n');
  const text=stripVTControlCharacters(render('after',mixed,['--side-by-side=hunk'],{...env,GIT_CONFIG_GLOBAL:formatFile}).toString());
  assert.ok(text.includes('1A'));
  assert.ok(text.includes('1B'));
  assert.match(text,/10\s*⋮\s*10\s*│ten/);
});
for (const name of ['rust-history','go-history']) for(const mode of [[],['--side-by-side']]) {
  test(`history has only the intended minus syntax difference ${name} ${mode}`,()=>{
    const input=fs.readFileSync(path.join(dir,'fixtures',name+'.diff'));
    const before=mode.length?render('before',input,[],{...env,GIT_CONFIG_GLOBAL:sideConfig}):render('before',input,mode),after=render('after',input,mode);
    if(before.equals(after))return;
    verifyDeletedFileColors(input,before,after);
  });
}
