package helpers

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/jesseduffield/lazygit/pkg/gocui"
	"github.com/jesseduffield/lazygit/pkg/gui/types"
)

func TestDeltaUpstreamConsumer(t *testing.T) {
	dir := os.Getenv("DELTA_BENCH_DIR")
	var expected []struct{ Kind, Line, Old, File string }
	data, err := os.ReadFile(filepath.Join(dir, "expected-records.json"))
	if err != nil { t.Fatal(err) }
	if err := json.Unmarshal(data, &expected); err != nil { t.Fatal(err) }
	want := map[string]bool{}
	for _, r := range expected {
		line, _ := strconv.Atoi(r.Line)
		old, _ := strconv.Atoi(r.Old)
		want[fmt.Sprintf("%s|%s|%d|%d", r.File, r.Kind, line, old)] = true
	}
	for _, file := range []string{"consumer-before-sbs.bin", "consumer-after-sbs.bin", "consumer-after-hunk.bin"} {
		t.Run(file, func(t *testing.T) {
			output, err := os.ReadFile(filepath.Join(dir, file))
			if err != nil { t.Fatal(err) }
			view := gocui.NewView("delta", 0, 0, 101, 41, gocui.OutputTrue)
			view.SetContent(string(output))
			contents := view.DiffLineContents()
			if !renderingStatesDiffLines(contents) { t.Fatal("renderer metadata not consumed") }
			got := map[string]bool{}
			for _, row := range contents {
				if strings.Contains(row.Text, "1717;") { t.Fatal("OSC metadata reached visible text") }
			}
			for _, row := range parseDiffLineIdentities(contents) {
				for _, r := range row {
					kind := ""
					switch r.Type {
					case types.DiffLineAdded: kind = "a"
					case types.DiffLineDeleted: kind = "d"
					case types.DiffLineContext: kind = "c"
					default: continue
					}
					got[fmt.Sprintf("%s|%s|%d|%d",r.Path,kind,r.NewLine,r.OldLine)] = true
				}
			}
			if len(got) != len(want) { t.Fatalf("got %d identities, want %d",len(got),len(want)) }
			for key := range want { if !got[key] { t.Errorf("missing actionable identity %s",key) } }
		})
	}
}

func TestDeltaUpstreamConsumerTimings(t *testing.T) {
	dir := os.Getenv("DELTA_BENCH_DIR")
	type sample struct { Fixture string `json:"fixture"`; Binary string `json:"binary"`; Pair int `json:"pair"`; Milliseconds float64 `json:"milliseconds"`; Identities int `json:"identities"` }
	var samples []sample
	for _, fixture := range []string{"go-1000", "go-12000"} {
		outputs := map[string]string{}
		for _, binary := range []string{"before", "after"} {
			file := filepath.Join(dir,"outputs/native",fixture+"-side-by-side-"+map[string]string{"before":"before","after":"clean"}[binary]+".bin")
			data,err := os.ReadFile(file); if err != nil {t.Fatal(err)}; outputs[binary]=string(data)
		}
		for pair := -3; pair < 15; pair++ {
			order := []string{"before","after"}; if pair%2 == 1 {order=[]string{"after","before"}}
			for _,binary := range order {
				start := time.Now()
				view := gocui.NewView("delta",0,0,101,41,gocui.OutputTrue)
				view.SetContent(outputs[binary])
				identities := parseDiffLineIdentities(view.DiffLineContents())
				elapsed := float64(time.Since(start).Nanoseconds())/1e6
				count := 0; for _,row := range identities {count+=len(row)}
				if count == 0 {t.Fatal("no actionable identities")}
				if pair >= 0 {samples=append(samples,sample{fixture,binary,pair,elapsed,count})}
			}
		}
	}
	data,err := json.MarshalIndent(samples,"","  "); if err != nil {t.Fatal(err)}
	if err := os.WriteFile(filepath.Join(dir,"lazygit-consumer-timings.json"),data,0644); err != nil {t.Fatal(err)}
}

