import fs from 'node:fs';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { performance } from 'node:perf_hooks';
import assert from 'node:assert/strict';

const dir=process.env.DELTA_BENCH_DIR||'/tmp/delta-merge-2026-11-11';
const manifest=JSON.parse(fs.readFileSync(path.join(dir,'manifest.json')));
const env={...process.env,...manifest.controls.environment};
delete env.DELTA_FEATURES;
const common=['--config',manifest.configuration.path,'--paging=never','--width=100','--true-color=always'];
const onlyLabel=process.env.DELTA_STREAM_LABEL;
const results=onlyLabel?JSON.parse(fs.readFileSync(path.join(dir,'extra-probes.json'))):{memory:[],streaming:[],cancellation:[],closedOutput:[]};
if(onlyLabel)results.streaming=results.streaming.filter(x=>x.label!==onlyLabel);
if(!onlyLabel)for(const [fixture,beforeArgs,afterArgs] of [
  ['long-lines',[],[]],['go-12000',['--lazygit-compat'],['--lazygit-compat']],['large-context',[],['--side-by-side=hunk']]
])for(let run=0;run<7;run++)for(const binary of run%2?['after','before']:['before','after']){
  const input=fs.readFileSync(manifest.fixtures.find(f=>f.name===fixture).path);
  const args=binary==='before'?beforeArgs:afterArgs;
  const maximum=await new Promise((resolve,reject)=>{
    const child=spawn(path.join(dir,binary),[...common,...args],{env,stdio:['pipe','ignore','pipe']});
    let highWater=0,error='';
    const timer=setInterval(()=>{try{const status=fs.readFileSync(`/proc/${child.pid}/status`,'utf8');const m=status.match(/^VmHWM:\s+(\d+)/m);if(m)highWater=Math.max(highWater,Number(m[1]));}catch{}},2);
    child.on('error',reject);child.stderr.on('data',b=>error+=b);child.stdin.on('error',reject);child.stdin.end(input);
    child.on('close',code=>{clearInterval(timer);if(code!==0)return reject(new Error(error));resolve(highWater);});
  });
  results.memory.push({fixture,binary,args,run,sampled_high_water_kib:maximum,sample_interval_ms:2});
}
const mixedPrefix=Buffer.from('diff --git a/stream.rs b/stream.rs\n--- a/stream.rs\n+++ b/stream.rs\n@@ -1,3 +1,4 @@\n first_visible\n-old();\n+new();\n visible_context\n');
const mixedSuffix=Buffer.from('+late\n');
const context=fs.readFileSync(manifest.fixtures.find(f=>f.name==='large-context').path);
const split=context.lastIndexOf(Buffer.from('+added\n'));
const middle=context.indexOf(Buffer.from(' context 10000\n'));
async function stream(binary,label,prefix,suffix,args){
  return await new Promise((resolve,reject)=>{
    const start=performance.now();
    const child=spawn(path.join(dir,binary),[...common,...args],{env,stdio:['pipe','pipe','pipe']});
    let firstOutput=null,firstBody=null,total=0;
    let text='';
    child.stdout.on('data',bytes=>{
      total+=bytes.length;
      const now=performance.now()-start;
      if(firstOutput===null)firstOutput=now;
      text=(text+bytes.toString()).slice(-2000000);
      if(firstBody===null&&(text.includes('first_visible')||text.includes('context 0')))firstBody=now;
    });
    let error='';child.stderr.on('data',b=>error+=b);
    child.on('error',reject);
    child.stdin.on('error',reject);
    child.stdin.write(prefix);
    const timer=setTimeout(()=>child.stdin.end(suffix),200);
    child.on('close',(code,signal)=>{
      clearTimeout(timer);
      if(code!==0)return reject(new Error(`${binary}: ${code}/${signal}: ${error}`));
      resolve({binary,label,args,producer_delay_ms:200,first_output_ms:firstOutput,first_body_ms:firstBody,completion_ms:performance.now()-start,output_bytes:total});
    });
  });
}
for(let run=0;run<7;run++)for(const binary of run%2?['after','before']:['before','after']){
  for(const [label,prefix,suffix,args]of[
    ['direct',mixedPrefix,mixedSuffix,[]],['native',mixedPrefix,mixedSuffix,['--lazygit-compat']],
    ['hunk-mixed',mixedPrefix,mixedSuffix,['--side-by-side'+(binary==='after'?'=hunk':'')]],
    ['hunk-one-sided-context',context.subarray(0,split),context.subarray(split),binary==='after'?['--side-by-side=hunk']:[]],
    ['hunk-partial-context',context.subarray(0,middle),context.subarray(middle),binary==='after'?['--side-by-side=hunk']:[]]
  ]){
    if(onlyLabel&&label!==onlyLabel)continue;
    results.streaming.push({run,...await stream(binary,label,prefix,suffix,args)});
  }
}
if(!onlyLabel){
for(const binary of ['before','after'])for(const args of [[],['--lazygit-compat']]){
  const result=await new Promise((resolve,reject)=>{
    const child=spawn(path.join(dir,binary),[...common,...args],{env,detached:true,stdio:['pipe','ignore','pipe']});
    child.on('error',reject);child.stdin.on('error',()=>{});child.stdin.write(mixedPrefix);
    setTimeout(()=>{process.kill(-child.pid,'SIGTERM');},30);
    child.on('close',(code,signal)=>resolve({binary,args,code,signal}));
  });
  assert.equal(result.signal,'SIGTERM');results.cancellation.push(result);
}
for(const binary of ['before','after'])for(const args of [[],['--lazygit-compat']]){
  const result=await new Promise((resolve,reject)=>{
    const child=spawn(path.join(dir,binary),[...common,...args],{env,stdio:['pipe','pipe','pipe']});
    let error='';child.stderr.on('data',b=>error+=b);
    child.on('error',reject);child.stdin.on('error',()=>{});
    child.stdout.once('data',()=>child.stdout.destroy());
    child.stdin.end(fs.readFileSync(manifest.fixtures.find(f=>f.name==='go-12000').path));
    child.on('close',(code,signal)=>resolve({binary,args,code,signal,stderr:error}));
  });
  results.closedOutput.push(result);
}
for(const native of [false,true]){
  const matching=results.closedOutput.filter(r=>Boolean(r.args.length)===native);
  assert.equal(matching[0].code,matching[1].code);
  assert.equal(matching[0].signal,matching[1].signal);
  assert.equal(matching[0].stderr,matching[1].stderr);
}
}
fs.writeFileSync(path.join(dir,'extra-probes.json'),JSON.stringify(results,null,2)+'\n');
console.log(path.join(dir,'extra-probes.json'));

scriptSources.output-differences.mjs:
import assert from 'node:assert/strict';

const stripSgr = text => text.replace(/\x1b\[[0-9;]*m/g, '');
const records = line => [...line.matchAll(/\x1b\]1717;1;([a-zA-Z]);([^;]*);([^;]*);([^\x1b\x07]*)(?:\x1b\\|\x07)/g)];

export function verifyDeletedFileColors(input, before, after) {
  const a=before.toString(), b=after.toString();
  assert.equal(stripSgr(a)===stripSgr(b), true, 'Output differs beyond SGR colors');
  const deletions=new Set();
  let commit='',deleted=false;
  for(const line of stripSgr(input.toString()).split('\n')) {
    if(line.startsWith('commit ')) commit=line.split(/\s+/)[1];
    if(line.startsWith('diff --git ')) deleted=false;
    if(line.startsWith('deleted file mode ')) deleted=true;
    if(deleted&&line.startsWith('--- a/')) deletions.add(`${commit}|${line.slice(6)}`);
  }
  const oldLines=a.split('\n'),newLines=b.split('\n');
  let changed=0;
  commit='';
  for(let i=0;i<oldLines.length;i++) {
    const row=records(oldLines[i]);
    for(const r of row)if(r[1]==='C')commit=r[4];
    if(oldLines[i]===newLines[i])continue;
    assert.ok(row.some(r=>['d','h'].includes(r[1])&&deletions.has(`${commit}|${r[4]}`)), `Color change outside a deleted-file content/header row at line ${i}`);
    changed++;
  }
  return {reason:'Correct syntax colors only on deleted-file content and hunk headers',changedRows:changed};
}

