func TestDeltaSGRCacheMatchesInterpreter(t *testing.T) {
	sequences := []string{"", "0", "1", "2", "3", "4", "7", "9", "22", "23", "24", "27", "29", "31", "39", "48;2;12;34;56", "38;2;108;112;134", "1;38;2;243;139;168", "38;5;88", "1;0;38;2;4;5;6", "38;02;1;2;3", "38;2;99999999999999999999;0;0", "31;38;2;1", "31;;2", "1;34;49", "999"}
	styles := []Attribute{ColorDefault, ColorRed, ColorBlue | AttrBold, NewRGBColor(108, 112, 134) | AttrUnderline, ^Attribute(0)}
	for _, mode := range []OutputMode{OutputNormal, Output256, OutputTrue} {
		cached := newEscapeInterpreter(mode)
		for _, seq := range sequences {
			for repeat := 0; repeat < 3; repeat++ {
				for _, fg := range styles {
					for _, bg := range styles {
						p := []byte("\x1b[" + seq + "mASCII")
						fresh := newEscapeInterpreter(mode)
						fresh.curFgColor, fresh.curBgColor = fg, bg
						cached.curFgColor, cached.curBgColor = fg, bg
						fresh.sgrCacheDisabled = true
						want := fresh.parseSGR(p)
						got := cached.parseSGR(p)
						if want != got || fresh.curFgColor != cached.curFgColor || fresh.curBgColor != cached.curBgColor || fresh.state != cached.state || fresh.curch != cached.curch {
							t.Fatalf("mode %v sequence %q initial %x/%x differs", mode, seq, fg, bg)
						}
					}
				}
			}
		}
	}
}

func TestDeltaSGRCacheBoundsUniqueInput(t *testing.T) {
	ei := newEscapeInterpreter(OutputTrue)
	for i := 0; i < 1000; i++ {
		ei.parseSGR([]byte(fmt.Sprintf("\x1b[38;2;%d;%d;%dmASCII", i%256, i/256, i%239)))
	}
	if !ei.sgrCacheDisabled || len(ei.sgrCache) != 0 {
		t.Fatal("unique input retained an unbounded cache")
	}
}

func TestDeltaSGRCacheFraming(t *testing.T) {
	for _, p := range []string{"\x1b[31m\u0301", "\x1b[31", "\x1b[?31m", "\x1b[31H"} {
		ei := newEscapeInterpreter(OutputTrue)
		ei.parseSGR([]byte("\x1b[31mASCII"))
		if ei.parseSGR([]byte(p)) != 0 {
			t.Fatalf("fast path consumed %q", p)
		}
	}
}

