package gocui

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/rivo/uniseg"
	"github.com/stretchr/testify/assert"
)

func TestDeltaSGRUnicodeBoundary(t *testing.T) {
	for _, text := range []string{"│", "中文", "🙂", "🇫🇷", "\u0600x", "\u0301", "\ufe0f", "\u200d🙂", "\u0903", "\u2028"} {
		sequence := "\x1b[1;38;2;125;150;200m"
		input := []byte(sequence + text)
		cluster, _, _, _ := uniseg.FirstGraphemeCluster([]byte("m"+text), -1)
		fast, slow := newEscapeInterpreter(OutputTrue), newEscapeInterpreter(OutputTrue)
		consumed := fast.parseSGR(input)
		if len(cluster) != 1 {
			assert.Zero(t, consumed, text)
			continue
		}
		assert.Equal(t, len(sequence), consumed, text)
		for _, c := range []byte(sequence) {
			_, err := slow.parseOne([]byte{c})
			assert.NoError(t, err)
		}
		assert.Equal(t, slow, fast, text)
	}
	for _, bytes := range [][]byte{{0xe2}, {0xf0, 0x9f}, {0xcc}} {
		input := append([]byte("\x1b[31m"), bytes...)
		assert.Zero(t, newEscapeInterpreter(OutputTrue).parseSGR(input))
	}
}

func TestDeltaSGRUnicodeChunkBoundaries(t *testing.T) {
	snapshots := map[string]string{}
	path := os.Getenv("DELTA_BENCH_DIR") + "/unicode-chunk-golden.json"
	generate := os.Getenv("DELTA_GENERATE_GOLDEN") == "1"
	if !generate {
		data, err := os.ReadFile(path)
		if err != nil {
			t.Fatal(err)
		}
		if err = json.Unmarshal(data, &snapshots); err != nil {
			t.Fatal(err)
		}
	}
	for _, text := range []string{"│text", "中文", "🙂", "\u0301text", "\ufe0ftext", "\u200d🙂"} {
		input := "\x1b[1;38;2;125;150;200m" + text + "\x1b[0m\n"
		for split := 0; split <= len(input); split++ {
			fast := NewView("fast", 0, 0, 80, 40, OutputTrue)
			fast.WriteString(input[:split])
			fast.WriteString(input[split:])
			key := fmt.Sprintf("%s/%d", text, split)
			state := fmt.Sprintf("%#v", fast.buf.lines)
			if generate {
				snapshots[key] = state
			} else {
				assert.Equal(t, snapshots[key], state, key)
			}
		}
	}
	if generate {
		data, err := json.MarshalIndent(snapshots, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err = os.WriteFile(path, data, 0644); err != nil {
			t.Fatal(err)
		}
	}
}

